using System;using System.IO;using System.IO.Compression;using System.Reflection;using System.Diagnostics;using System.Drawing;using System.Windows.Forms;using Microsoft.Win32;
[assembly:AssemblyVersion("0.1.2.4")]
class InstallForm:Form {
 const string PayloadHash="__PAYLOAD_HASH__",ProductId="__PRODUCT_ID__",Version="0.1.2.4-beta",Entry="SteamSafe.exe";
 TextBox path=new TextBox();CheckBox desktop=new CheckBox(),launch=new CheckBox();Button install=new Button(),browse=new Button();ProgressBar progress=new ProgressBar();Label status=new Label();
 public InstallForm(){Text="SteamSafe Beta 安装向导";ClientSize=new Size(650,380);Font=new Font("Microsoft YaHei UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;
  var title=new Label(){Text="安装 SteamSafe",Font=new Font(Font.FontFamily,20,FontStyle.Bold),Location=new Point(25,25),AutoSize=true};Controls.Add(title);
  Controls.Add(new Label(){Text="管理员版 · "+Version+" · 内置 Python 运行时",Location=new Point(28,75),AutoSize=true});
  Controls.Add(new Label(){Text="安装目录",Location=new Point(28,115),AutoSize=true});path.SetBounds(28,145,490,30);path.Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"SteamSafeBeta","v0.1.2.4-"+ProductId.Substring(ProductId.Length-8));Controls.Add(path);
  browse.Text="浏览…";browse.SetBounds(530,144,90,32);browse.Click+=delegate{using(var d=new FolderBrowserDialog()){d.Description="选择本地管理员控制的安装目录";d.SelectedPath=path.Text;if(d.ShowDialog(this)==DialogResult.OK)path.Text=d.SelectedPath;}};Controls.Add(browse);
  Controls.Add(new Label(){Text="目录必须位于管理员控制的本地位置；拒绝游戏目录、系统目录及重解析点。",Location=new Point(28,184),Size=new Size(590,40)});
  desktop.Text="创建桌面快捷方式";desktop.Checked=true;desktop.SetBounds(28,224,280,28);Controls.Add(desktop);
  launch.Text="安装完成后启动";launch.Checked=true;launch.SetBounds(325,224,240,28);Controls.Add(launch);
  progress.SetBounds(28,262,590,18);Controls.Add(progress);status.SetBounds(28,291,590,30);Controls.Add(status);
  install.Text="安装";install.SetBounds(420,330,90,32);install.Click+=delegate{StartInstall();};Controls.Add(install);var cancel=new Button(){Text="取消",Location=new Point(530,330),Size=new Size(90,32)};cancel.Click+=delegate{Close();};Controls.Add(cancel);
 }
 void StartInstall(){try{string target=SetupSecurity.Destination(path.Text);SetupSecurity.PendingDeletion(target);SetupSecurity.ParentPolicy(target);if(Directory.Exists(target))SetupSecurity.ValidateAcl(target,false);install.Enabled=false;browse.Enabled=false;path.Enabled=false;status.Text="验证并安装…";Application.DoEvents();Install(target,desktop.Checked);progress.Value=100;status.Text="安装完成，已注册应用卸载入口。";if(launch.Checked)Process.Start(new ProcessStartInfo(Path.Combine(target,Entry)){UseShellExecute=true,WorkingDirectory=target});MessageBox.Show(this,"安装完成。卸载可从 Windows 设置、开始菜单或 Uninstall.exe 启动。","SteamSafe");Close();}catch(Exception e){install.Enabled=true;browse.Enabled=true;path.Enabled=true;status.Text="安装未完成";MessageBox.Show(this,e.Message,"安装未完成",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 static void Shortcut(string file,string target,string arguments){SetupSecurity.NoLinks(Path.GetDirectoryName(file));SetupSecurity.NoLinks(file);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));if(File.Exists(file)){dynamic prior=shell.CreateShortcut(file);string previous=(string)prior.TargetPath;if(!previous.Equals(target,StringComparison.OrdinalIgnoreCase)){if(Path.GetFileName(previous)!="SteamSafe.exe")throw new Exception("已有同名快捷方式属于其他程序");SetupSecurity.CheckSignature(previous);}}dynamic link=shell.CreateShortcut(file);link.TargetPath=target;link.Arguments=arguments;link.WorkingDirectory=Path.GetDirectoryName(target);link.IconLocation=target+",0";link.Save();File.SetAccessControl(file,SetupSecurity.FilePolicy());}
 static void Install(string destination,bool desktop){SetupSecurity.MakeDir(destination);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip")){if(SetupSecurity.Hash(stream)!=PayloadHash)throw new Exception("发行载荷校验失败");stream.Position=0;using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var e in zip.Entries){if(e.FullName.EndsWith("/"))continue;string target=SetupSecurity.Within(destination,e.FullName);string dir=Path.GetDirectoryName(target);string cursor=destination;foreach(string part in dir.Substring(destination.Length).Split(new[]{Path.DirectorySeparatorChar},StringSplitOptions.RemoveEmptyEntries)){cursor=Path.Combine(cursor,part);SetupSecurity.MakeDir(cursor);}string expected;using(var input=e.Open())expected=SetupSecurity.Hash(input);if(File.Exists(target)){if(SetupSecurity.FileHash(target)!=expected)throw new Exception("现有文件不匹配，请退出旧程序并选择新的独立目录："+target);}else using(var input=e.Open())using(var output=new FileStream(target,FileMode.CreateNew,System.Security.AccessControl.FileSystemRights.Write,FileShare.None,81920,FileOptions.None,SetupSecurity.FilePolicy()))input.CopyTo(output);File.SetAccessControl(target,SetupSecurity.FilePolicy());}}}
  string menuRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms),"SteamSafe Beta");SetupSecurity.MakeDir(menuRoot);string menu=Path.Combine(menuRoot,ProductId);SetupSecurity.MakeDir(menu);Shortcut(Path.Combine(menu,"SteamSafe.lnk"),Path.Combine(destination,Entry),"");Shortcut(Path.Combine(menu,"卸载 SteamSafe.lnk"),Path.Combine(destination,"Uninstall.exe"),"");
  if(desktop)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory),"SteamSafe Beta.lnk"),Path.Combine(destination,Entry),"");
  using(var key=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+ProductId)){key.SetValue("DisplayName","SteamSafe Beta");key.SetValue("DisplayVersion",Version);key.SetValue("Publisher","SteamSafe Beta Project");key.SetValue("InstallLocation",destination);key.SetValue("DisplayIcon",Path.Combine(destination,Entry));key.SetValue("UninstallString","\""+Path.Combine(destination,"Uninstall.exe")+"\"");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);key.SetValue("DesktopShortcut",desktop?1:0);key.SetValue("StartMenu",menu);}
 }
 [STAThread] static int Main(string[] args){try{SetupSecurity.CheckSelf();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new InstallForm()){if(args.Length==2&&args[0]=="--ui-smoke"){f.Show();f.PerformLayout();Application.DoEvents();IntPtr handle=f.Handle;using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(args[1]);}return 0;}if(args.Length==2&&args[0]=="--self-test"){int n=0;foreach(var p in new[]{@"C:\",Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"C:\Steam\steamapps\common\Game",@"\\server\share\App"}){try{SetupSecurity.Destination(p);throw new Exception("unsafe destination accepted");}catch(Exception e){if(e.Message=="unsafe destination accepted")throw;}n++;}string root=Path.GetDirectoryName(args[1]);foreach(var p in new[]{"../escape.dll",@"C:\escape.dll","file:ads"}){try{SetupSecurity.Within(root,p);throw new Exception("unsafe relative accepted");}catch(Exception e){if(e.Message=="unsafe relative accepted")throw;}n++;}File.WriteAllText(args[1],"{\"ok\":true,\"tests\":"+n+"}");return 0;}Application.Run(f);}return 0;}catch(Exception e){if(args.Length>0){Console.Error.WriteLine(e.Message);return 1;}MessageBox.Show(e.Message,"安装器验证失败",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
}
